class LoadScfFileModal(ConfirmationModal):
    _CLOSE_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[@a-text="Close"]/button'

    def __init__(self, driver):
        super(LoadScfFileModal, self).__init__(driver)
        self._load_scf_nodes = 4

    def wait_until_load_file_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)

    @wait_for_operation_success(2, ElementClickInterceptedException)
    def confirm(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._CLOSE_BUTTON_XPATH), timeout)

    def check_status_after_loading_scf_file(self, check_node=4, timeout=60):
        """
        Check status after loading scf file
        """
        load_scf_file_node_status_xpath = '//div[@class="modal-body"]//ul//li[{}]'
        for index in range(1, self._load_scf_nodes + 1):
            node_status_xpath = load_scf_file_node_status_xpath.format(index)
            self.wait_for_text_present_in_attribute(node_status_xpath, "class", "ng-scope")
            node_status = self.get_attribute_by_xpath(node_status_xpath, "class", timeout)
            if "failed" in node_status:
                return False
        return True


class RatOperationModal(ConfirmationModal):
    _CLOSE_BUTTON = '//div[@class="modal-content"]//button[contains(text(), "Close")]'
    _TECHNOLOGY_RADIO = '//label[@for="{}"]'
    _BAND_BUTTON_XPATH = '//*[contains(@*, "{}")]//button'
    _BAND_TABLE_LI_XPATH = '//*[contains(@*, "{}")]//li'
    _BAND_CHECKBOX_XPATH = '//*[contains(@*, "{}")]//li//input'
    _TECHNOLOGY_BAND_MAPPING = {
        'NR': 'NRBands',
        'LTE': 'LTEBands',
        'WCDMA': 'WCDMABands',
        'GSM': 'GSMBands',
    }

    def __init__(self, driver):
        super(RatOperationModal, self).__init__(driver)

    def wait_for_rat_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)

    def select_technology(self, technology):
        try:
            self.click_enabled_element((By.XPATH, self._TECHNOLOGY_RADIO.format(technology)))
        except TimeoutException:
            raise TimeoutException('{} can not be chosen, pls check your webem if it is enable')

    def select_band(self, technology, bands):
        band_label = self._TECHNOLOGY_BAND_MAPPING[technology]
        self.click_and_wait_for_corresponding_element_visible(self._BAND_BUTTON_XPATH.format(band_label),
                                                              self._BAND_TABLE_LI_XPATH.format(band_label))

        for element in self.driver.find_elements_by_xpath(self._BAND_CHECKBOX_XPATH.format(band_label)):
            span_item = element.find_element_by_xpath('./parent::span')
            self.driver.execute_script("arguments[0].scrollIntoView();", span_item)
            is_checked = element.is_selected()
            if not is_checked and span_item.text in bands:
                span_item.click()
            elif is_checked and span_item.text not in bands:
                span_item.click()

    def close_rat_modal(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._CLOSE_BUTTON), timeout)


class AddRatModal(RatOperationModal):
    _ADD_BUTTON = '//div[@class="modal-content"]//button[contains(text(), "Add")]'
    _LOAD_SCF_FILE_BUTTON_SCRIPT = '.add-scf-rat input'
    _LOAD_SCF_FILE_BUTTON_XPATH = '//*[contains(@class, "add-scf-rat")]//input'
    _LOAD_SCF_SUCCEED = 'Load SCF succeed'
    _LOAD_SCF_SUCCEED_STATUS_XPATH = '//*[contains(@ng-show, "isLoadSuccess")]'
    _SUCCESS_STATUS_XPATH = '//*[contains(@ng-show, "isAddSuccess")]'
    _VALIDATION_MSG = '//validation-message'

    def __init__(self, driver):
        super(AddRatModal, self).__init__(driver)

    def load_scf_file(self, scf_file_path, timeout=60):
        self.load_file_from_hidden_button_in_sbts(
            self._LOAD_SCF_FILE_BUTTON_SCRIPT,
            self._LOAD_SCF_FILE_BUTTON_XPATH,
            scf_file_path,
            timeout
        )
        self.wait_for_text_present_in_element((By.XPATH, self._LOAD_SCF_SUCCEED_STATUS_XPATH),
                                              self._LOAD_SCF_SUCCEED,
                                              timeout)

    def click_add(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._ADD_BUTTON), timeout)
        try:
            self.wait_for_text_not_present_in_attribute(self._SUCCESS_STATUS_XPATH,
                                                        'class',
                                                        'hide',
                                                        10)
            outcome = self.get_text_by_xpath(self._SUCCESS_STATUS_XPATH, timeout)
        except TimeoutException:
            outcome = self.get_text_by_xpath(self._VALIDATION_MSG, timeout)
        self.close_rat_modal(timeout)
        return outcome


