class ActivatePlanModal(ConfirmationModal):
    """
    Class for activate plan modal, providing methods to manipulate elements on modal
    """
    _EXECUTE_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[@a-text="Execute"]/button'
    _CLOSE_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[@a-text="Close"]/button'
    _DOWNLOAD_PLAN_LABEL_XPATH = '//span[contains(text(), "Download plan without activation")]'
    _DOWNLOAD_PLAN_CHECKBOX_XPATH = ('//span[contains(text(), "Download plan without activation")]'
                                     '/preceding-sibling::input')
    _ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_LABEL_XPATH = ('//span[contains(text(), '
                                                             '"plan despite of validation errors")]')
    _ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_INPUT_XPATH = ('//span[contains(text(), "plan despite of validation '
                                                             'errors")]/preceding-sibling::input')
    _FEEDBACK_TEXT_XPATH = '//div[@class="modal-content"]//div[@class="feedback-section"]/div[2]'

    def __init__(self, driver):
        super(ActivatePlanModal, self).__init__(driver)

    def wait_until_actiavte_plan_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)

    def close(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._CLOSE_BUTTON_XPATH), timeout)

    def _execute_under_granular_timeout(self, timeout):
        minimum_timeout = 2
        flag = False
        for _ in range(int(timeout / minimum_timeout)):
            if not flag and self.check_if_prompt_bts_reset(minimum_timeout):
                self.wait_for_enable((By.XPATH, self._EXECUTE_BUTTON_XPATH))
                self.driver.execute_script('arguments[0].click();',
                                           self.driver.find_element_by_xpath(self._EXECUTE_BUTTON_XPATH))
                flag = True

            if self.check_if_activate_successfully(minimum_timeout):
                return True
        return False

    def execute(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._EXECUTE_BUTTON_XPATH), timeout)
        return self._execute_under_granular_timeout(timeout)

    def select_download_plan_without_activation(self, download_plan_without_activation=False):
        self.select_checkbox_by_specified_status(download_plan_without_activation,
                                                 self._DOWNLOAD_PLAN_CHECKBOX_XPATH,
                                                 self._DOWNLOAD_PLAN_LABEL_XPATH)

    def select_activate_or_download_plan_despite_errors(self, activate_plan_despite_errors=False, timeout=60):
        if self.element_exists((By.XPATH, self._ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_LABEL_XPATH), timeout):
            self.select_checkbox_by_specified_status(activate_plan_despite_errors,
                                                     self._ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_INPUT_XPATH,
                                                     self._ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_LABEL_XPATH)

    def check_if_prompt_bts_reset(self, timeout=60):
        return self.check_if_element_has_text((By.XPATH, self._FEEDBACK_TEXT_XPATH), 'reset', timeout)

    def check_if_activate_successfully(self, timeout=60):
        return self.check_if_element_has_text((By.XPATH, self._FEEDBACK_TEXT_XPATH), 'successfully', timeout)


