class SaveBtsConfigurationModal(ConfirmationModal):
    _SAVE_CONFIGURATION_TYPE_MAIN_XPATH = "//div[@class='modal-body']//label[text()='{}']"

    _SAVE_PLANNED_PARAMETERS_CHANGES_CHECK_XPATH = "//div[@class='modal-body']//input[contains(@type, 'checkbox')]"
    _SAVE_PLANNED_PARAMETERS_CHANGES_CHECK_FOR_CLICK_XPATH = ("//div[@class='modal-body']"
                                                              "//span[text()='Save also planned parameters changes']")
    _SAVE_CONFIGURATION_MODAL_CLASS = "//ui-modal[@a-title='Save BTS Configuration']"

    def __init__(self, driver, download_checker):
        super(SaveBtsConfigurationModal, self).__init__(driver, download_checker)

    def wait_until_save_bts_configuration_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._SAVE_CONFIGURATION_MODAL_CLASS), timeout)

    def save(self, save_configuration_type_str, is_save_planned_parameter_changes_selected):
        save_configuration_button_xpath = "//div[@class='modal-footer']//ui-button[@a-text='Save']/button"
        self._set_save_configuration_type(save_configuration_type_str, is_save_planned_parameter_changes_selected)
        start_time = time.time()
        self.click_enabled_element((By.XPATH, save_configuration_button_xpath))
        return self.download_files(start_time)

    def cancel(self):
        cancel_configuration_button_xpath = "//div[@class='modal-footer']//ui-button[@a-text='Cancel']/button"
        self.click_enabled_element(cancel_configuration_button_xpath)

    def _set_save_configuration_type(self, save_configuration_type_str, is_save_planned_parameter_changes_selected):
        self.click_element_by_xpath(self._SAVE_CONFIGURATION_TYPE_MAIN_XPATH.format(save_configuration_type_str))
        if self.element_exists((By.XPATH, self._SAVE_PLANNED_PARAMETERS_CHANGES_CHECK_XPATH)):
            element = self.driver.find_element_by_xpath(self._SAVE_PLANNED_PARAMETERS_CHANGES_CHECK_XPATH)
            if element.is_enabled() and is_save_planned_parameter_changes_selected != element.is_selected():
                self.click_element_by_xpath(self._SAVE_PLANNED_PARAMETERS_CHANGES_CHECK_FOR_CLICK_XPATH)


