class BtsStartUpViewModal(ConfirmationModal):
    _MODAL_XPATH = '//div[@class="modal-content"]//ui-modal[@*="BTS Start-up View"]'
    _RMOD = 'RMOD'
    _SUCCEED = 'Succeed'
    _CELLS_NAME = ['2G cells', '3G cells', '4G cells', 'NR cells']
    _CELL_CATEGORY = 4

    def __init__(self, driver):
        super(BtsStartUpViewModal, self).__init__(driver)

    def wait_for_start_up_view_modal_appear(self, timeout=10):
        try:
            self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)
            return True
        except TimeoutException:
            logging.info('start up view window is not exist')
            return False

    def get_bts_start_up_view_info(self):
        _BTS_START_UP_VIEW_INFO_VALUE_XPATH = '//*[@*="BTS Start-up View"]//h5'

        info = {}
        for title_elem in self.driver.find_elements_by_xpath(_BTS_START_UP_VIEW_INFO_VALUE_XPATH):
            keys, values = self._get_keys_and_values(title_elem)

            if keys[0] in self._CELLS_NAME:
                data = {}
                for index in range(int(len(keys) / self._CELL_CATEGORY)):
                    cell_keys = keys[index * 4: index * 4 + 4]
                    cell_keys.insert(1, 'Status')
                    name = cell_keys.pop(0)
                    cell_values = values[index * 4: index * 4 + 4]
                    cell_info = dict(zip(cell_keys, cell_values))
                    data.update({name: cell_info})
            else:
                data = dict(zip(keys, values))

            info.update({title_elem.text: data})
        return info

    def _get_keys_and_values(self, root_elem):
        keys = []
        values = []
        for index, _ in enumerate(root_elem.find_elements_by_xpath('./following-sibling::div//label')):
            elem = root_elem.find_elements_by_xpath('./following-sibling::div//label')[index]
            key = elem.text.strip(':')
            keys.append(key)

            if self._RMOD in key:
                values.append(self._SUCCEED)
                continue

            span = elem.find_elements_by_xpath('./following-sibling::span')
            if not span:
                values.append("")
                continue

            values.append(span[0].text)
        return keys, values

    def close(self, timeout=10):
        _CLOSE_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[@a-text="Close"]/button'
        self.click_enabled_element((By.XPATH, _CLOSE_BUTTON_XPATH), timeout)


