class LoadRamlProfileModal(ConfirmationModal):
    _TITLE = '//span[text()="Load Raml Profile"]'
    _UPLOAD_PROFILE = '//p-fileupload[@class="upload-profile"]'
    _UPLOAD_PROFILE_FILE_BUTTON_SCRIPT = 'p-fileupload[class="upload-profile"] input'
    _UPLOAD_PROFILE_FILE_BUTTON_XPATH = '//p-fileupload[@class="upload-profile"]//input'
    _UPLOAD_STATUS = '//p-fileupload/../following-sibling::div//span[last()]'
    _APPLY = '//button[*[text()="Apply"]]'
    _CANCEL = '//button[*[text()="Cancel"]]'

    def __init__(self, driver):
        super(LoadRamlProfileModal, self).__init__(driver)

    def wait_until_load_raml_profile_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._TITLE), timeout)

    def upload_profile(self, file_path, timeout=60):
        self.wait_for_visibility_by_xpath(self._UPLOAD_PROFILE)
        self.load_file_from_hidden_button_in_sbts(self._UPLOAD_PROFILE_FILE_BUTTON_SCRIPT,
                                                  self._UPLOAD_PROFILE_FILE_BUTTON_XPATH,
                                                  file_path,
                                                  timeout)

    def _get_upload_status(self, timeout=30):
        self.wait_for_visibility_by_xpath(self._UPLOAD_STATUS, timeout)
        return self.get_text_by_xpath(self._UPLOAD_STATUS)

    def apply(self, apply_for_warning, timeout=30):
        status = self._get_upload_status(timeout)
        if 'warning' in status and apply_for_warning is True:
            self.click_enabled_element((By.XPATH, self._APPLY), timeout)
            return status

        if 'warning' in status and apply_for_warning is False:
            self.click_enabled_element((By.XPATH, self._CANCEL), timeout)
            return status

        if 'failed' in status:
            self.click_enabled_element((By.XPATH, self._CANCEL), timeout)
            return status

        self.click_enabled_element((By.XPATH, self._APPLY), timeout)
        return status


